    en: { title: 'How to Change Address in Aadhaar Online — Step by Step, Documents, Fee (2026) | NextGrade', desc: 'The full way to change your Aadhaar address from home: log in on the myAadhaar portal, which documents are accepted, the fee, how to check status and common reasons for rejection.', h1: '🏠 How to change your address in Aadhaar (online)', quick: [['Where', 'myAadhaar portal (from uidai.gov.in)'], ['You need', 'Mobile number linked to Aadhaar (for OTP)'], ['Fee', 'Shown on the portal — ₹75 at present as per UIDAI'], ['Time', 'Usually a few days, up to 30 days']], docs: ['Proof of address — e.g. electricity/water/gas bill (not older than 3 months), bank passbook/statement, passport, voter ID, registered rent agreement', 'Your name on the document must match Aadhaar', 'Clear scan/photo — PDF, JPG or PNG (the portal shows the size limit)'], steps: [['Log in to myAadhaar', 'Open myaadhaar.uidai.gov.in → Login.', ['Aadhaar number (12 digits)', 'Captcha', 'OTP sent to your mobile']], ['Choose "Address Update"', 'On the dashboard: "Document Update / Address Update" (the label may differ slightly) → "Update Aadhaar Online".', ['Select Address', '"Proceed to Update Aadhaar"']], ['Enter the new address', 'Your current address is shown; type the new one below.', ['C/O (care of)', 'House number, street, locality', 'Village/town, post office, district, state, PIN code', 'Check the local-language address too']], ['Upload the document', 'Pick your document from the list and upload the file.', ['Document type — e.g. Electricity Bill', 'File — clear, full page, name and address visible']], ['Pay and keep the URN', 'Pay online (UPI/card/net banking). You get a URN (Update Request Number) at the end — take a screenshot.', ['Payment', 'Note down the URN']]], status: 'Check the status under "Check Enrolment & Update Status" on myAadhaar with your URN. Once updated, download the new e-Aadhaar with "Download Aadhaar".', reject: ['Name on the document differs from Aadhaar', 'Blurred or cropped image', 'Old bill (more than 3 months)', 'Wrong PIN code or district'], faq: [['How long does an Aadhaar address change take?', 'Usually a few days; up to 30 days. Track it with the URN.'], ['Can I change the address without my own document?', 'There is also an option using the Head of Family’s document and consent; see the options on the portal.'], ['My mobile is not linked to Aadhaar — what now?', 'Link it first at an Aadhaar centre (book at appointments.uidai.gov.in). The online update needs an OTP.']] },
