export const SARKARI_NAV = Object.fromEntries(Object.entries(UI).map(([k, v]) => [k, v.nav]));
const LOC = { hi: 'hi-IN', bn: 'bn-IN', en: 'en-IN', hinglish: 'en-IN' };

export function buildSarkari(L, { page, write, P, esc, T, breadcrumbLd }) {
  const code = L.code, U = UI[code], hub = '/sarkari-guide/';
  const checked = new Intl.DateTimeFormat(LOC[code], { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }).format(new Date(`${CHECKED}T00:00:00Z`));
  const css = '<style>section.sg-step{padding:16px 18px}.sg-step{background:var(--surface);border:1px solid var(--line);border-radius:16px;margin:14px 0;box-shadow:var(--shadow)}.sg-step h3{margin:0 0 6px;font-size:19px}.sg-step .n{display:inline-grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#1c7ed6;color:#fff;font-size:15px;margin-right:8px}.sg-quick{width:100%;border-collapse:collapse;margin:10px 0}.sg-quick td{padding:8px 10px;border-bottom:1px solid var(--line)}.sg-quick td:first-child{font-weight:700;width:34%}.sg-note{color:#1f2937;background:#e7f5ff;border-left:4px solid #1c7ed6;padding:12px 16px;border-radius:12px}.sg-warn{color:#3b2a1a;background:#fff4e6;border-left:4px solid #e8590c;padding:12px 16px;border-radius:12px}.sg-gov{font-size:14px;color:var(--muted);border:1px dashed var(--line);padding:10px 14px;border-radius:10px}</style>';
  write(L, hub, page(L, {
    path: hub, title: U.hubTitle, description: U.hubDesc,
    jsonLd: [breadcrumbLd(L, [[T.nav.home, '/'], [U.nav, hub]])],
    body: `${css}<div class="wrap article">
<p class="crumbs"><a href="${P(L, '/')}">${esc(T.nav.home)}</a> › ${esc(U.nav)}</p>
<h1>${esc(U.hubH1)}</h1>
<p class="lead">${esc(U.hubLead)}</p>
<div class="grid">${G.map(([s, e, , , X]) => `<a class="card" href="${P(L, `${hub}${s}/`)}"><span class="emoji" aria-hidden="true">${e}</span><h3>${esc(X[code].h1.replace(/^\S+\s/, ''))}</h3><p>${esc(X[code].quick.map(([a, b]) => `${a}: ${b}`).slice(0, 2).join(' · '))}</p></a>`).join('')}</div>
<p class="sg-gov">${esc(U.notGov)}</p>
</div>`,
  }));
  for (const [slug, emoji, links, home, X] of G) {
    const x = X[code], path = `${hub}${slug}/`;
    const howTo = { '@context': 'https://schema.org', '@type': 'HowTo', name: x.h1.replace(/^\S+\s/, ''), description: x.desc, step: x.steps.map(([h, b], i) => ({ '@type': 'HowToStep', position: i + 1, name: h, text: b, url: links[i] })) };
    const faqLd = { '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: x.faq.map(([q, a]) => ({ '@type': 'Question', name: q, acceptedAnswer: { '@type': 'Answer', text: a } })) };
    write(L, path, page(L, {
      path, title: x.title, description: x.desc,
      jsonLd: [breadcrumbLd(L, [[T.nav.home, '/'], [U.nav, hub], [x.h1.replace(/^\S+\s/, ''), path]]), howTo, faqLd],
      body: `${css}<div class="wrap narrow article">
<p class="crumbs"><a href="${P(L, '/')}">${esc(T.nav.home)}</a> › <a href="${P(L, hub)}">${esc(U.nav)}</a> › ${esc(x.h1.replace(/^\S+\s/, ''))}</p>
<h1>${esc(x.h1)}</h1>
<p class="note">${esc(U.checked(checked))}</p>
<h2>${esc(U.quickH)}</h2>
<table class="sg-quick">${x.quick.map(([a, b]) => `<tr><td>${esc(a)}</td><td>${esc(b)}</td></tr>`).join('')}</table>
<p><a class="btn btn-primary" href="${home}" target="_blank" rel="noopener">${esc(U.open)}</a></p>
<h2>${esc(U.docsH)}</h2><ul>${x.docs.map((t) => `<li>${esc(t)}</li>`).join('')}</ul>
<div class="ad" aria-hidden="true"></div>
${x.steps.map(([h, b, f], i) => `<section class="sg-step"><h3><span class="n">${i + 1}</span>${esc(h)}</h3><p>${esc(b)}</p><p><b>${esc(U.fillL)}</b></p><ul>${f.map((t) => `<li>${esc(t)}</li>`).join('')}</ul><p><a href="${links[i]}" target="_blank" rel="noopener">${esc(U.open)}</a></p></section>`).join('\n')}
<h2>${esc(U.statusH)}</h2><p>${esc(x.status)}</p>
<h2>${esc(U.rejectH)}</h2><ul>${x.reject.map((t) => `<li>${esc(t)}</li>`).join('')}</ul>
<div class="sg-warn"><b>${esc(U.scamH)}</b><ul>${U.scam.map((t) => `<li>${esc(t)}</li>`).join('')}</ul></div>
<h2>${esc(U.toolsH)}</h2><p class="chips">${U.tools.map(([h, t]) => `<a class="tag" href="${h}">${esc(t)}</a>`).join(' ')}</p>
<div class="ad" aria-hidden="true"></div>
<h2>${esc(U.faqH)}</h2>${x.faq.map(([q, a]) => `<h3>${esc(q)}</h3><p>${esc(a)}</p>`).join('')}
<p class="sg-note">${esc(U.change)}</p>
<p class="sg-gov">${esc(U.notGov)}</p>
<h2>${esc(U.others)}</h2><p class="chips">${G.filter(([s]) => s !== slug).map(([s, e, , , Y]) => `<a class="tag" href="${P(L, `${hub}${s}/`)}">${e} ${esc(Y[code].h1.replace(/^\S+\s/, ''))}</a>`).join(' ')}</p>
</div>`,
    }));
  }
}
